import numpy as np
from itertools import product

def is_valid(S):
    N = S.shape[0]
    r = S.sum(axis=1)
    c = S.sum(axis=0)
    reserved = []
    for i in range(N):
        for j in range(N):
            if S[i, j] == 1:
                if (r[i], c[j]) in reserved:
                    return False
                reserved.append((r[i], c[j]))
    return True

