def random_search(N, iterations=100000):
    max_m = 0
    for _ in range(iterations):
        S = np.random.randint(0, 2, (N, N))
        if is_valid(S):
            r = S.sum(axis=1)
            for m in range(N, 0, -1):
                if np.sum(r == m) >= 2:
                    max_m = max(max_m, m)
                    break
    return max_m

