def find_max_m_conditions(N):
    for m in range(N, 0, -1):
        for k in range(1, N + 1):
            for l in range(1, N + 1):
                rem_rows = N
                S_row = 0
                for r in range(N, 0, -1):
                    if r == m:
                        if rem_rows < 2 or 2*m > k:
                            S_row = -1
                            break
                        take = min(rem_rows, k // m)
                        S_row += take * m
                        rem_rows -= take
                    else:
                        take = min(rem_rows, k // r)
                        S_row += take * r
                        rem_rows -= take
                if S_row == -1: continue
                S_col_max = 0
                for c in range(N, N - k, -1):
                    S_col_max += (l // c) * c
                S_col_min = 0
                for c in range(1, k + 1):
                    S_col_min += 1 * c
                if S_col_min <= S_row <= S_col_max:
                    return m
    return 0

